VALUES
  ('a1111111-1111-4111-8111-111111111111', '1b844c73-a627-4477-9c74-a95c7da2c71e', 'Floral Print Maxi Dress', 'Elegant floral print maxi dress perfect for special occasions. Features a flowing silhouette and comfortable fit. A Small Street Mall favourite.', 'MELI-001', 349.00, 499.00, 18, ARRAY['XS','S','M','L','XL'], ARRAY['Floral Pink','Floral Blue','Black'], 'https://images.pexels.com/photos/18593350/pexels-photo-18593350.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', true, true, false),
  ('a1111111-1111-4111-8111-111111111111', '1b844c73-a627-4477-9c74-a95c7da2c71e', 'Knit Top with Shoulder Cutouts', 'Trendy knit top with stylish shoulder cutouts. Lightweight and breathable, ideal for Johannesburg summers.', 'MELI-002', 189.00, 249.00, 25, ARRAY['S','M','L'], ARRAY['Cream','Black','Olive'], 'https://images.pexels.com/photos/11311403/pexels-photo-11311403.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', true, true, false),
  ('a1111111-1111-4111-8111-111111111111', '1b844c73-a627-4477-9c74-a95c7da2c71e', 'Satin Wrap Dress', 'Luxurious satin wrap dress that drapes beautifully. Perfect for evening events and dinner dates.', 'MELI-003', 429.00, null, 12, ARRAY['XS','S','M','L'], ARRAY['Burgundy','Emerald','Black'], 'https://images.pexels.com/photos/18250201/pexels-photo-18250201.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', false, true, false),
  ('a1111111-1111-4111-8111-111111111111', '1b844c73-a627-4477-9c74-a95c7da2c71e', 'Two-Piece Print Set', 'Matching two-piece set with bold African-inspired prints. Includes crop top and wide-leg trousers.', 'MELI-004', 549.00, 699.00, 8, ARRAY['S','M','L','XL'], ARRAY['Multi Print','Earth Tones'], 'https://images.pexels.com/photos/34777778/pexels-photo-34777778.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', true, true, false),
  ('a1111111-1111-4111-8111-111111111111', 'd5b98645-8ece-4b33-9862-cb97cf9dbd08', 'Classic Tracksuit Set', 'Comfortable tracksuit set for casual wear. Soft cotton blend with elastic waistband and matching jacket.', 'MELI-005', 399.00, null, 20, ARRAY['S','M','L','XL','XXL'], ARRAY['Grey','Navy','Black'], 'https://images.pexels.com/photos/27208599/pexels-photo-27208599.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', false, true, false),
  ('a1111111-1111-4111-8111-111111111111', '1b844c73-a627-4477-9c74-a95c7da2c71e', 'Sequin Evening Gown', 'Show-stopping sequin evening gown for special occasions. Catches the light with every movement.', 'MELI-006', 799.00, 999.00, 5, ARRAY['XS','S','M','L'], ARRAY['Gold','Silver','Rose Gold'], 'https://images.pexels.com/photos/14452644/pexels-photo-14452644.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', true, true, false),
  ('a1111111-1111-4111-8111-111111111111', 'd7710705-9c45-45c7-a32b-886d0e4cfe1e', 'Strappy Heeled Sandals', 'Elegant strappy heeled sandals to complement any outfit. Comfortable padded insole for all-day wear.', 'MELI-007', 299.00, null, 15, ARRAY['36','37','38','39','40'], ARRAY['Black','Nude','Red'], 'https://images.pexels.com/photos/31450745/pexels-photo-31450745.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', false, true, false),
  ('a1111111-1111-4111-8111-111111111111', '68de9415-9a2f-4171-8278-3ef66aedb0b3', 'Leather Handbag with Tassel', 'Genuine leather handbag with decorative tassel. Spacious interior with multiple compartments.', 'MELI-008', 459.00, 599.00, 10, ARRAY['One Size'], ARRAY['Tan','Black','Brown'], 'https://images.pexels.com/photos/31450723/pexels-photo-31450723.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', false, true, false)
